1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Objects;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
10	
11	/**
12	 * On create, rejects the owner when another owner already shares its last name and address
13	 * (compared case-insensitively with collapsed whitespace). Skipped when the request opts in
14	 * via {@code sharesHousehold=true}.
15	 */
16	public class EnsureUniqueOwnerHousehold {
17	
18	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository)
19	            throws DuplicateHouseholdException {
20	        String household = household(owner);
21	        owner.setHouseholdId(Integer.toHexString(household.hashCode()).toUpperCase());
22	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
23	            return;
24	        }
25	        for (Owner existing : ownerRepository.findAll()) {
26	            if (!Objects.equals(existing.getId(), owner.getId())
27	                    && household.equals(household(existing))) {
28	                throw new DuplicateHouseholdException(
29	                        "Another owner already shares this last name and address");
30	            }
31	        }
32	    }
33	
34	    private static String household(Owner owner) {
35	        return normalize(owner.getLastName()) + '\n' + normalize(owner.getAddress());
36	    }
37	
38	    private static String normalize(String value) {
39	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
40	    }
41	}
