3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * On create, records how many owners share this owner's household (matched by
9	 * {@code householdId}) once this one joins, as {@code householdSize}. Runs after the household id
10	 * is assigned and before {@code SaveOwner}, so the not-yet-persisted owner is counted via the
11	 * seeded count of one.
12	 */
13	public class AssignOwnerHouseholdSize {
14	
15	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
16	        int count = 1;
17	        for (Owner existing : ownerRepository.findAll()) {
18	            if (owner.getHouseholdId() != null
19	                    && owner.getHouseholdId().equals(existing.getHouseholdId())) {
20	                count++;
21	            }
22	        }
23	        owner.setHouseholdSize(count);
24	    }
25	}
