1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Objects;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	/**
9	 * Response value: the id of an earlier owner this one soft-matches, or null when there is
10	 * none. A soft-match shares the earlier owner's lastName and postcode but has a different
11	 * (normalized) telephone, so it is not a hard {@link IdentityKey} duplicate.
12	 */
13	final class PossibleDuplicate {
14	
15	    private PossibleDuplicate() {
16	    }
17	
18	    static Integer of(Owner owner, OwnerRepository ownerRepository) {
19	        String postcode = owner.getPostcode();
20	        if (postcode == null || owner.getId() == null) {
21	            return null;
22	        }
23	        String telephone = digits(owner.getTelephone());
24	        for (Owner existing : ownerRepository.findAll()) {
25	            if (existing.getId() != null && existing.getId() < owner.getId()
26	                    && postcode.equals(existing.getPostcode())
27	                    && Objects.equals(owner.getLastName(), existing.getLastName())
28	                    && !telephone.equals(digits(existing.getTelephone()))) {
29	                return existing.getId();
30	            }
31	        }
32	        return null;
33	    }
34	
35	    private static String digits(String telephone) {
36	        return telephone == null ? "" : telephone.replaceAll("\\D", "");
37	    }
38	}
