1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * The single duplicate-detection key for an owner:
7	 * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. Two owners
8	 * are duplicates only when their whole identity keys are equal.
9	 */
10	final class IdentityKey {
11	
12	    private IdentityKey() {
13	    }
14	
15	    static String of(Owner owner) {
16	        return digits(owner.getTelephone()) + '|' + orEmpty(owner.getEmail()) + '|' + orEmpty(owner.getHouseholdId());
17	    }
18	
19	    private static String digits(String telephone) {
20	        return telephone == null ? "" : telephone.replaceAll("\\D", "");
21	    }
22	
23	    private static String orEmpty(String value) {
24	        return value == null ? "" : value;
25	    }
26	}
