3	import java.util.Objects;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
9	
10	/**
11	 * On create, rejects the owner when its whole {@link IdentityKey} (normalized telephone,
12	 * email and household id) equals an existing owner's. This is the single consolidated
13	 * duplicate check: owners collide only on an exact full-key match, so two members of the
14	 * same household with different telephones are both allowed.
15	 */
16	public class EnsureUniqueOwnerIdentity {
17	
18	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
19	            throws DuplicateIdentityException {
20	        String identityKey = IdentityKey.of(owner);
21	        for (Owner existing : ownerRepository.findAll()) {
22	            if (!Objects.equals(existing.getId(), owner.getId())
23	                    && identityKey.equals(IdentityKey.of(existing))) {
24	                throw new DuplicateIdentityException("An owner with the same identity already exists");
25	            }
26	        }
27	    }
28	}
