1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.mapper.Locality;
9	import org.springframework.samples.petclinic.model.Owner;
10	
11	/**
12	 * On create, assigns the owner's {@code customerCode} as '&lt;REGION&gt;-&lt;HASH8&gt;', where REGION is
13	 * the region code derived from the postcode (NSW/VIC/QLD, else UNKNOWN) and HASH8 is the first eight
14	 * upper-case hex characters of SHA-256 over the normalized telephone concatenated with the last name
15	 * (e.g. 'NSW-1A2B3C4D'). Runs after the telephone has been normalized so the hash is stable, and there
16	 * are no sequence numbers.
17	 */
18	public class AssignOwnerCustomerCode {
19	
20	    public void service(@Val Owner owner) {
21	        String region = Locality.of(null, owner.getPostcode());
22	        String hash8 = sha256Hex(orEmpty(owner.getTelephone()) + orEmpty(owner.getLastName())).substring(0, 8);
23	        owner.setCustomerCode(region + "-" + hash8.toUpperCase());
24	    }
25	
26	    private static String orEmpty(String value) {
27	        return value == null ? "" : value;
28	    }
29	
30	    private static String sha256Hex(String value) {
31	        try {
32	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
33	            StringBuilder hex = new StringBuilder(digest.length * 2);
34	            for (byte b : digest) {
35	                hex.append(String.format("%02x", b));
36	            }
37	            return hex.toString();
38	        } catch (NoSuchAlgorithmException ex) {
39	            throw new IllegalStateException(ex);
40	        }
41	    }
42	}
