11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials",
24	        expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
25	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
26	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
27	    @Mapping(target = "locality", expression = "java(owner.getCustomerCode() != null && owner.getCustomerCode().indexOf('-') > 0 ? owner.getCustomerCode().substring(0, owner.getCustomerCode().indexOf('-')) : Locality.of(owner.getCity(), owner.getPostcode()))")
28	    OwnerDto toOwnerDto(Owner owner);
29	
30	    /** Numeric level 1-3 assigned on creation: starts at 1, +1 when an email is present,
31	     * +1 when namesakeCount is 0, capped at 3 (level 4 is reserved for tenure). */
32	    default Integer membershipLevel(Owner owner) {
33	        int level = 1;
34	        if (owner.getEmail() != null) {
35	            level++;
36	        }
37	        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
38	            level++;
39	        }
40	        return Math.min(level, 3);
41	    }
42	
43	    /** '&lt;customerCode&gt;-M&lt;YY&gt;', YY = last two digits of the registrationDate year; null when either input is absent. */
44	    default String membershipNumber(Owner owner) {
45	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
46	            return null;
47	        }
48	        return owner.getCustomerCode() + "-M" + String.format("%02d", owner.getRegistrationDate().getYear() % 100);
49	    }
50	
51	    Owner toOwner(OwnerDto ownerDto);
52	
53	    @Mapping(target = "id", ignore = true)
54	    @Mapping(target = "pets", ignore = true)
55	    Owner toOwner(OwnerFieldsDto ownerDto);
56	
57	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
58	
59	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
60	
61	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
62	        OwnerPageDto ownerPageDto = new OwnerPageDto();
63	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
64	        ownerPageDto.setPage(ownerPage.getNumber());
65	        ownerPageDto.setSize(ownerPage.getSize());
66	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
67	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
68	        return ownerPageDto;
69	    }
70	}
