11	import org.springframework.validation.annotation.Validated;
12	import org.springframework.web.bind.annotation.RequestBody;
13	
14	@Validated
15	public class BuildOwner {
16	
17	    public void service(@Valid @RequestBody OwnerFieldsDto request, OwnerMapper ownerMapper,
18	            Out<Owner> built, Out<OwnerFieldsDto> requestOut) throws RegistrationDateInFutureException {
19	        Owner owner = ownerMapper.toOwner(request);
20	        if (owner.getRegistrationDate() == null) {
21	            owner.setRegistrationDate(LocalDate.now());
22	        }
23	        else if (owner.getRegistrationDate().isAfter(LocalDate.now())) {
24	            throw new RegistrationDateInFutureException("Registration date must not be later than today");
25	        }
26	        built.set(owner);
27	        requestOut.set(request);
28	    }
29	}
