        for (Owner existing : ownerRepository.findAll()) {
            if (owner.getHouseholdId() != null
                    && owner.getHouseholdId().equals(existing.getHouseholdId())) {
                count++;
            }
        }
        owner.setHouseholdSize(count);
    }
}

